import pandas as pd
from sklearn.preprocessing import LabelEncoder

def task_func(data):
    if isinstance(data, (str, bytes)):
        raise TypeError("data must be an iterable of categorical values, not a string scalar.")

    try:
        values = list(data)
    except TypeError as exc:
        raise TypeError("data must be an iterable of categorical values.") from exc

    if len(values) == 0:
        return pd.DataFrame(columns=["Category", "Encoded"])

    for value in values:
        try:
            is_missing = bool(pd.isna(value))
        except (TypeError, ValueError):
            is_missing = False
        if is_missing:
            raise ValueError("data must not contain missing values.")

    encoder = LabelEncoder()
    encoder.fit(values)

    return pd.DataFrame(
        {
            "Category": encoder.classes_,
            "Encoded": encoder.transform(encoder.classes_),
        }
    )
